#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdarg.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <limits.h>
#include <errno.h>
#include <time.h>
static int once_open,once_write,once_sync;
static int target_path(const char *p) {
 char resolved[PATH_MAX]; const char *target=getenv("PROGRESS_TARGET");
 return target && realpath(p,resolved) && !strcmp(resolved,target);
}
static int target_fd(int fd) {
 char link[64],path[PATH_MAX];snprintf(link,sizeof link,"/proc/self/fd/%d",fd);
 ssize_t n=readlink(link,path,sizeof path-1);if(n<0)return 0;path[n]=0;
 const char *target=getenv("PROGRESS_TARGET");return target&&!strcmp(path,target);
}
static int gate(const char *phase,int *once) {
 char env[64],ready[PATH_MAX],release[PATH_MAX];
 snprintf(env,sizeof env,"PROGRESS_%s",phase);
 if(*once||!getenv(env))return 0;*once=1;
 const char *home=getenv("HOME");snprintf(ready,sizeof ready,"%s/%s.ready",home,phase);
 snprintf(release,sizeof release,"%s/%s.release",home,phase);
 int fd=open(ready,O_WRONLY|O_CREAT|O_TRUNC,0600);if(fd<0)return -1;close(fd);
 for(int i=0;i<1500;i++){if(access(release,F_OK)==0)return 0;usleep(10000);}
 errno=ETIMEDOUT;return -1;
}
static int do_open(const char *symbol,const char *path,int flags,mode_t mode) {
 int (*real_open)(const char*,int,...)=dlsym(RTLD_NEXT,symbol);
 if((flags&(O_WRONLY|O_RDWR))&&target_path(path)){
  if(gate("OPEN",&once_open)<0)return -1;
  if(getenv("FAIL_OPEN")){errno=EACCES;return -1;}
 }
 return real_open(path,flags,mode);
}
int open(const char *path,int flags,...) {
 mode_t mode=0;if(flags&O_CREAT){va_list a;va_start(a,flags);mode=va_arg(a,int);va_end(a);}
 return do_open("open",path,flags,mode);
}
int open64(const char *path,int flags,...) {
 mode_t mode=0;if(flags&O_CREAT){va_list a;va_start(a,flags);mode=va_arg(a,int);va_end(a);}
 return do_open("open64",path,flags,mode);
}
int fsync(int fd) {
 int (*real_sync)(int)=dlsym(RTLD_NEXT,"fsync");
 if(target_fd(fd)){
  if(gate("SYNC",&once_sync)<0)return -1;
  if(getenv("FAIL_SYNC")){errno=EIO;return -1;}
 }
 return real_sync(fd);
}
ssize_t write(int fd,const void *data,size_t n) {
 ssize_t (*real_write)(int,const void*,size_t)=dlsym(RTLD_NEXT,"write");
 if(target_fd(fd)&&gate("WRITE",&once_write)<0)return -1;
 return real_write(fd,data,n);
}
size_t fwrite(const void *data,size_t size,size_t count,FILE *stream) {
 size_t (*real_write)(const void*,size_t,size_t,FILE*)=dlsym(RTLD_NEXT,"fwrite");
 if(target_fd(fileno(stream))&&gate("WRITE",&once_write)<0)return 0;
 return real_write(data,size,count,stream);
