#!/usr/bin/python3
import os,time
h=os.environ['HOME']; pidfile=h+'/open.pid'; ready=h+'/open.ready'
deadline=time.time()+10
pid=None
while time.time()<deadline:
 try: pid=int(open(pidfile).read().strip()); break
 except (FileNotFoundError,ValueError): time.sleep(.01)
if pid is None: raise SystemExit(2)
wchan='/proc/%d/wchan'%pid
seen=False
while time.time()<deadline:
 try:
  state=open(wchan).read().strip()
  if state and state not in ('0','running'): seen=True; break
 except FileNotFoundError: break
 time.sleep(.01)
if not seen: raise SystemExit(3)
os.unlink(pidfile)
open(ready,'w').write('wait_for_partner\n')

